// ============================================================================
// FAO Reserve Recon - Validate Invoke Body
// ----------------------------------------------------------------------------
// FAO-GOV-007 / FAO-GOV-008: the invoke webhook accepts exactly one field,
// body.run_token, a single-use token issued by fao_run_start to a signed-in
// human. The token is the real gate: fao_run_claim refuses unknown, expired
// and already used tokens. This node only checks its shape.
//
// Every other body field, every query parameter and every header is ignored.
// Identity, agent and tier never come from the request; they come from the
// database through Claim Run.
// ============================================================================

const TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;

const first = $input.first();
const payload = first && first.json ? first.json : {};
const body = payload.body;

let candidate;
if (body !== null && typeof body === 'object' && !Array.isArray(body)) {
  candidate = body.run_token;
}

const valid = typeof candidate === 'string' && TOKEN_PATTERN.test(candidate);

return [{
  json: {
    valid,
    run_token: valid ? candidate : null,
    n8n_execution_id: $execution.id
  }
}];

// ============================================================================
// FAO Reserve Reconciliation Agent - Init Execution
// ----------------------------------------------------------------------------
// FAO-GOV-008: correlation_id, execution_id, agent_id and risk_tier come from
// the database, read from the Claim Run result (fao_run_claim). The workflow
// never generates run identifiers and never names the invoker; the database
// recorded the invoker from the caller's own session at run start and adds
// it to the STARTED event itself.
// FAO-REC-001: emits the STARTED event in the Writer input shape (one event,
// no hitl_approver_id, no event_timestamp). The asset scope is the sorted
// union of wallet and ledger keys, the same set Per-Asset Reconcile walks.
//
// FIXTURE DESIGN (calibrated against Kraken Dec 2025 PoR + control coverage):
//   BTC, ETH, XRP - wallet/ledger calibrated to Kraken's published Dec 31,
//                   2025 PoR ratios (1.003, 1.013, 1.006 respectively).
//   USDC          - clean exact-match baseline.
//   USDT          - synthetic anomaly: stablecoin USD-materiality breach
//                   (FAO-REC-002).
//   SOL           - synthetic anomaly: under-reservation floor violation
//                   (FAO-REC-004).
//   ADA           - synthetic anomaly: negative liability, krakendb 2014
//                   precedent (FAO-REC-007).
//
// Source URL for real-anchored assets:
//   https://blog.kraken.com/news/december-2025-proof-of-reserves
//
// In production, wallet_data comes from Fireblocks API and ledger_data from
// NetSuite GL. Inline embedding here isolates policy logic from data-source
// plumbing; file reads and API calls move in post-launch.
//
// _wallet_data, _ledger_data and _fixture_metadata are internal fields for
// Per-Asset Reconcile; the Writer's Validate Batch strips every key that
// starts with an underscore.
// ============================================================================

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const AGENT_PATTERN = /^[a-z0-9_]{1,64}$/;
const SYMBOL_PATTERN = /^[A-Z0-9]{1,12}$/;
const TIERS = ['GREEN', 'AMBER', 'RED'];

const claim = (($('Claim Run').first() || {}).json || {}).r;
if (!claim || typeof claim !== 'object' || claim.ok !== true) {
  throw new Error('FAO-GOV-008 recon: claim result is missing or not ok');
}
if (typeof claim.correlation_id !== 'string' || !UUID_PATTERN.test(claim.correlation_id)) {
  throw new Error('FAO-GOV-008 recon: claim result has no valid correlation_id');
}
if (typeof claim.execution_id !== 'string' || !UUID_PATTERN.test(claim.execution_id)) {
  throw new Error('FAO-GOV-008 recon: claim result has no valid execution_id');
}
if (typeof claim.agent_id !== 'string' || !AGENT_PATTERN.test(claim.agent_id)) {
  throw new Error('FAO-GOV-008 recon: claim result has no valid agent_id');
}
if (!TIERS.includes(claim.risk_tier)) {
  throw new Error('FAO-GOV-008 recon: claim result has no valid risk_tier');
}

const correlation_id = claim.correlation_id;
const execution_id   = claim.execution_id;
const agent_id       = claim.agent_id;
const risk_tier      = claim.risk_tier;

// --- Fixture: simulated on-chain wallet holdings (Fireblocks proxy) -------
const wallet_data = {
  BTC:  167690.25,        // anchored to Kraken Dec 2025 PoR (ratio 1.003)
  ETH:  2884112,          // anchored to Kraken Dec 2025 PoR (ratio 1.013)
  USDC: 891723456,        // synthetic clean exact-match baseline
  USDT: 1234567890.50,    // synthetic stablecoin USD-materiality anomaly
  SOL:  8740000,          // synthetic under-reservation anomaly (ratio 0.95)
  XRP:  128265000,        // anchored to Kraken Dec 2025 PoR (ratio 1.006)
  ADA:  47293847          // wallet positive; ledger intentionally negative
};

// --- Fixture: simulated internal client-liability ledger (NetSuite proxy) -
const ledger_data = {
  BTC:  167188.68,
  ETH:  2847100,
  USDC: 891723456,
  USDT: 1234500000,
  SOL:  9200000,
  XRP:  127500000,
  ADA:  -150000           // FAO-REC-007 trigger, krakendb 2014 precedent
};

// --- Fixture provenance metadata (threaded into shadow_ledger evidence) ---
// Recorded once per run on the STARTED row under inputs.fixture_provenance.
const fixture_metadata = {
  BTC:  { source: 'kraken_por_2025_q4_anchor',  reference_url: 'https://blog.kraken.com/news/december-2025-proof-of-reserves', notes: 'Wallet/ledger calibrated to published Dec 31 2025 ratio 100.3%' },
  ETH:  { source: 'kraken_por_2025_q4_anchor',  reference_url: 'https://blog.kraken.com/news/december-2025-proof-of-reserves', notes: 'Wallet/ledger calibrated to published Dec 31 2025 ratio 101.3%' },
  USDC: { source: 'synthetic_clean_baseline',   notes: 'Exact match; exercises the in-band ALLOW path with zero discrepancy' },
  USDT: { source: 'synthetic_anomaly',          control: 'FAO-REC-002', notes: 'Stablecoin USD-materiality breach: ratio in band but absolute USD discrepancy exceeds threshold' },
  SOL:  { source: 'synthetic_anomaly',          control: 'FAO-REC-004', notes: 'Under-reservation: ratio 0.95 below floor 1.00' },
  XRP:  { source: 'kraken_por_2025_q4_anchor',  reference_url: 'https://blog.kraken.com/news/december-2025-proof-of-reserves', notes: 'Wallet/ledger calibrated to published Dec 31 2025 ratio 100.6%' },
  ADA:  { source: 'synthetic_anomaly',          control: 'FAO-REC-007', notes: 'Negative liability; krakendb 2014 reference implementation precedent' }
};

// Asset scope: sorted union of both sides, so an asset present on one side
// only is still in scope and is recorded (BLOCKED) by Per-Asset Reconcile.
const asset_scope = Array.from(
  new Set([...Object.keys(wallet_data), ...Object.keys(ledger_data)])
).sort();

if (asset_scope.length < 1 || asset_scope.length > 50) {
  throw new Error(`FAO-REC-001 recon: asset scope must hold 1 to 50 assets, found ${asset_scope.length}`);
}
for (const sym of asset_scope) {
  if (!SYMBOL_PATTERN.test(sym)) {
    throw new Error('FAO-REC-001 recon: fixture asset symbol is not a valid symbol');
  }
}

const asset_count = asset_scope.length;

return [{
  json: {
    // --- Writer event (Writer input shape) ---------------------------------
    correlation_id,
    event_type:          'STARTED',
    execution_id,
    agent_id,
    risk_tier,
    inputs: {
      event_type:         'STARTED',
      asset_scope:        asset_scope,
      asset_count:        asset_count,
      wallet_source:      'fixture://wallet_data.json (Fireblocks proxy)',
      ledger_source:      'fixture://ledger_data.json (NetSuite proxy)',
      fixture_provenance: fixture_metadata
    },
    ai_prompt:           null,
    ai_output:           null,
    ai_confidence:       null,
    fractional_cost_usd: null,
    policy_outcome:      'ALLOW',
    policy_sub_tier:     null,
    policy_rationale:    `FAO-REC-001 ${agent_id} execution started. Reconciling ${asset_count} assets (${asset_scope.join(', ')}) against materiality thresholds. Risk tier: ${risk_tier}. Fixture mix: 3 Kraken Dec 2025 PoR anchors + 1 clean baseline + 3 synthetic control anomalies.`,
    obligations:         [],
    hitl_status:         'NOT_REQUIRED',
    status:              'SUCCESS',
    error_details:       null,

    // --- Internal context (underscore prefix; stripped by Validate Batch) --
    _wallet_data:      wallet_data,
    _ledger_data:      ledger_data,
    _fixture_metadata: fixture_metadata
  }
}];

// ============================================================================
// FAO Reserve Recon - Check Thresholds
// ----------------------------------------------------------------------------
// FAO-REC-002: zero threshold rows are a hard error, not a silent stop.
// Get Materiality Thresholds runs with alwaysOutputData, so an empty result
// arrives here as one empty item. Unless at least one item carries a string
// asset_symbol, the run fails at this node and the error workflow records it.
// Items pass through unchanged.
// ============================================================================

const items = $input.all();

const usable = items.filter(it => it && it.json && typeof it.json.asset_symbol === 'string');
if (usable.length === 0) {
  throw new Error('FAO-REC-002 recon: no materiality thresholds for scope=Spot');
}

return items;

// ============================================================================
// FAO Reserve Reconciliation Agent - Per-Asset Reconcile (observe + decide)
// ----------------------------------------------------------------------------
// Controls implemented:
//   FAO-REC-001  Wallet-Ledger Balance Comparison (completeness, input checks)
//   FAO-REC-002  Per-Asset Materiality Threshold Evaluation
//   FAO-REC-004  Reserve Ratio Threshold Check
//   FAO-REC-006  Policy Outcome Engine (expected-ratio band evaluation)
//   FAO-REC-007  Negative-Balance Anomaly Detection (krakendb precedent)
//
// Design note: observation and decision are one ASSET_RECONCILED event per
// asset (one row per asset is the audit grain).
//
// Fail-closed input rules (evaluated before the matrix):
//   a. asset present on one side only    -> BLOCKED, band_status ONE_SIDED
//   b. a balance that is not a finite
//      number (undefined, null, empty,
//      non_numeric, nan, infinite)        -> BLOCKED, band_status INVALID_INPUT
//   c. no usable threshold for the asset  -> BLOCKED, band_status NO_THRESHOLD
// Every BLOCKED item carries hitl_status PENDING and ratio null: BLOCKED
// routes the run to human review (the database rollup decides that).
//
// Decision matrix (deterministic, evaluated top-down, first match wins):
//   1. ledger < 0           -> REQUIRE_HUMAN CRITICAL (FAO-REC-007)
//   2. ledger == 0          -> REQUIRE_HUMAN STANDARD (cannot compute ratio)
//   3. ratio < floor        -> REQUIRE_HUMAN CRITICAL (under-reserved)
//   4. ratio > band_upper   -> REQUIRE_HUMAN STANDARD (unexpected surplus)
//   5. Stablecoin AND |discrepancy| > materiality_usd
//                           -> REQUIRE_HUMAN STANDARD (USD threshold breach)
//   6. ratio < band_lower   -> ALLOW_WITH_OBLIGATIONS (drift below band)
//   7. otherwise            -> ALLOW (in expected band)
//
// Note on USD materiality test: applied only to stablecoins because for
// stablecoins, raw units == USD value (1 USDC = $1). For non-stablecoins,
// applying USD materiality requires a price oracle, which is out of scope.
//
// Assets are walked in the sorted union of wallet and ledger keys, the same
// order and set as the STARTED asset_scope. Each output item is one Writer
// event (no hitl_approver_id, no event_timestamp).
// ============================================================================

const ctx    = $('Init Execution').first().json;
const wallet = ctx._wallet_data || {};
const ledger = ctx._ledger_data || {};
const has    = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key);

// Threshold lookup; rows without a string asset_symbol (the empty item that
// alwaysOutputData produces) are ignored.
const threshold_by_asset = {};
for (const item of $input.all()) {
  const t = item && item.json;
  if (t && typeof t.asset_symbol === 'string') threshold_by_asset[t.asset_symbol] = t;
}

// num(v): a finite number, or a string that parses to one. Anything else is
// classified so the input problem can be named without echoing the value.
const DECIMAL = /^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/;
function num(v) {
  if (v === undefined) return { ok: false, cls: 'undefined' };
  if (v === null) return { ok: false, cls: 'null' };
  if (typeof v === 'number') {
    if (Number.isNaN(v)) return { ok: false, cls: 'nan' };
    if (!Number.isFinite(v)) return { ok: false, cls: 'infinite' };
    return { ok: true, value: v };
  }
  if (typeof v === 'string') {
    const s = v.trim();
    if (s === '') return { ok: false, cls: 'empty' };
    if (/^nan$/i.test(s)) return { ok: false, cls: 'nan' };
    if (/^[+-]?infinity$/i.test(s)) return { ok: false, cls: 'infinite' };
    if (!DECIMAL.test(s)) return { ok: false, cls: 'non_numeric' };
    const n = Number(s);
    if (Number.isNaN(n)) return { ok: false, cls: 'nan' };
    if (!Number.isFinite(n)) return { ok: false, cls: 'infinite' };
    return { ok: true, value: n };
  }
  return { ok: false, cls: 'non_numeric' };
}

const finite = (v) => typeof v === 'number' && Number.isFinite(v);
function usable_threshold(t) {
  return !!t
    && finite(t.ratio_floor) && finite(t.ratio_band_lower)
    && finite(t.ratio_band_upper) && finite(t.materiality_usd)
    && typeof t.asset_class === 'string';
}

const assets = Array.from(new Set([...Object.keys(wallet), ...Object.keys(ledger)])).sort();
const output_items = [];

for (const asset of assets) {
  const in_wallet = has(wallet, asset);
  const in_ledger = has(ledger, asset);

  // (a) One-sided: the asset is missing from one side entirely.
  if (!in_wallet || !in_ledger) {
    const missing = in_wallet ? 'ledger' : 'wallet';
    const present = in_wallet ? num(wallet[asset]) : num(ledger[asset]);
    output_items.push({ json: blocked(asset, {
      wallet: in_wallet && present.ok ? present.value : null,
      ledger: in_ledger && present.ok ? present.value : null,
      band_status: 'ONE_SIDED',
      input_problem: `${missing} balance missing`,
      threshold: threshold_facts(threshold_by_asset[asset]),
      rationale: `FAO-REC-001 ${asset}: ${missing} balance missing; the asset is present on one side only. Asset BLOCKED and routed to human review.`,
      error_details: `Asset ${asset} has no ${missing} balance`
    }) });
    continue;
  }

  // (b) Invalid balance on either side.
  const wv = num(wallet[asset]);
  const lv = num(ledger[asset]);
  if (!wv.ok || !lv.ok) {
    const problems = [];
    if (!wv.ok) problems.push(`wallet value is ${wv.cls}`);
    if (!lv.ok) problems.push(`ledger value is ${lv.cls}`);
    const problem = problems.join('; ');
    output_items.push({ json: blocked(asset, {
      wallet: wv.ok ? wv.value : null,
      ledger: lv.ok ? lv.value : null,
      band_status: 'INVALID_INPUT',
      input_problem: problem,
      threshold: threshold_facts(threshold_by_asset[asset]),
      rationale: `FAO-REC-001 ${asset}: ${problem}; the balance is not a finite number. Asset BLOCKED and routed to human review.`,
      error_details: `Asset ${asset} input problem: ${problem}`
    }) });
    continue;
  }

  const w = wv.value;
  const l = lv.value;
  const t = threshold_by_asset[asset];

  // (c) No usable threshold.
  if (!usable_threshold(t)) {
    output_items.push({ json: blocked(asset, {
      wallet: w, ledger: l,
      band_status: 'NO_THRESHOLD',
      input_problem: null,
      threshold: null,
      rationale: `FAO-REC-002 ${asset}: no materiality threshold configured for scope=Spot. Asset BLOCKED pending Controller setup. Cannot evaluate.`,
      error_details: `Asset ${asset} not present in materiality_thresholds (scope=Spot)`
    }) });
    continue;
  }

  const discrepancy = w - l;

  // ----- Decision matrix --------------------------------------------------
  let outcome, sub_tier, rationale, hitl_status, obligations = [];
  let ratio = null;
  let band_status;

  if (l < 0) {
    // (1) Negative liability - FAO-REC-007 (krakendb precedent)
    band_status      = 'NEGATIVE_LEDGER';
    outcome          = 'REQUIRE_HUMAN';
    sub_tier         = 'CRITICAL';
    hitl_status      = 'PENDING';
    rationale        = `FAO-REC-007 ${asset} negative liability detected (ledger=${l}). Cannot compute meaningful ratio. Routed to CRITICAL HITL; Controller + CFO review required (RED tier, 2 approvers). Pattern flagged in krakendb 2014 reference implementation as operational concern.`;
  } else if (l === 0) {
    // (2) Zero ledger - division undefined
    band_status      = 'ZERO_LEDGER';
    outcome          = 'REQUIRE_HUMAN';
    sub_tier         = 'STANDARD';
    hitl_status      = 'PENDING';
    rationale        = `FAO-REC-006 ${asset} zero ledger balance with non-zero wallet (${w}). Cannot compute reserve ratio. Manual review required.`;
  } else {
    ratio = w / l;

    if (ratio < t.ratio_floor) {
      // (3) Under-reserved - the worst case
      band_status   = 'BELOW_FLOOR';
      outcome       = 'REQUIRE_HUMAN';
      sub_tier      = 'CRITICAL';
      hitl_status   = 'PENDING';
      rationale     = `FAO-REC-004 ${asset} ratio ${ratio.toFixed(6)} below floor ${t.ratio_floor.toFixed(4)}. UNDER-RESERVED; wallet holdings insufficient to cover ledger liabilities. Routed to CRITICAL HITL (RED tier, 2 approvers).`;
    } else if (ratio > t.ratio_band_upper) {
      // (4) Unexpected surplus - investigate ledger
      band_status   = 'ABOVE_BAND_UPPER';
      outcome       = 'REQUIRE_HUMAN';
      sub_tier      = 'STANDARD';
      hitl_status   = 'PENDING';
      rationale     = `FAO-REC-006 ${asset} ratio ${ratio.toFixed(6)} above expected band upper ${t.ratio_band_upper.toFixed(4)}. Unexpected surplus; possible ledger under-recording. Investigate liability side.`;
    } else if (t.asset_class === 'Stablecoin' && Math.abs(discrepancy) > t.materiality_usd) {
      // (5) Stablecoin USD materiality breach (units == USD for stablecoins)
      band_status   = 'IN_BAND_USD_MATERIAL';
      outcome       = 'REQUIRE_HUMAN';
      sub_tier      = 'STANDARD';
      hitl_status   = 'PENDING';
      rationale     = `FAO-REC-002 ${asset} stablecoin: ratio ${ratio.toFixed(6)} within band [${t.ratio_band_lower.toFixed(4)}, ${t.ratio_band_upper.toFixed(4)}], BUT absolute discrepancy $${Math.abs(discrepancy).toFixed(2)} exceeds materiality threshold $${t.materiality_usd.toFixed(2)}. Stablecoin units are 1:1 USD; small ratio deviations on large pools are still material.`;
    } else if (ratio < t.ratio_band_lower) {
      // (6) Drift below expected band - not under-reserved (above floor)
      band_status   = 'BELOW_BAND_LOWER';
      outcome       = 'ALLOW_WITH_OBLIGATIONS';
      sub_tier      = null;
      hitl_status   = 'NOT_REQUIRED';
      obligations   = ['weekly_review_required', 'flag_drift_pattern_to_controller'];
      rationale     = `FAO-REC-006 ${asset} ratio ${ratio.toFixed(6)} below expected band lower ${t.ratio_band_lower.toFixed(4)} but above floor ${t.ratio_floor.toFixed(4)}. Reserves cover liabilities but over-reservation posture has drifted. Allowed with weekly-review obligation.`;
    } else {
      // (7) In expected band - clean
      band_status   = 'IN_BAND';
      outcome       = 'ALLOW';
      sub_tier      = null;
      hitl_status   = 'NOT_REQUIRED';
      rationale     = `FAO-REC-006 ${asset} ratio ${ratio.toFixed(6)} within expected band [${t.ratio_band_lower.toFixed(4)}, ${t.ratio_band_upper.toFixed(4)}]. Reserved as expected.`;
    }
  }

  output_items.push({ json: build_writer_event(ctx, {
    asset, wallet: w, ledger: l,
    ratio, discrepancy, band_status,
    threshold: threshold_facts(t),
    input_problem:    null,
    policy_outcome:   outcome,
    policy_sub_tier:  sub_tier,
    policy_rationale: rationale,
    hitl_status:      hitl_status,
    obligations:      obligations,
    status:           'SUCCESS',
    error_details:    null
  }) });
}

return output_items;

// ----- Helpers --------------------------------------------------------------
function threshold_facts(t) {
  if (!usable_threshold(t)) return null;
  return {
    asset_class:      t.asset_class,
    ratio_floor:      t.ratio_floor,
    ratio_band_lower: t.ratio_band_lower,
    ratio_band_upper: t.ratio_band_upper,
    materiality_usd:  t.materiality_usd
  };
}

// BLOCKED items: fail closed, routed to review, no ratio.
function blocked(asset, f) {
  return build_writer_event(ctx, {
    asset, wallet: f.wallet, ledger: f.ledger,
    ratio: null, discrepancy: null, band_status: f.band_status,
    threshold: f.threshold,
    input_problem:    f.input_problem,
    policy_outcome:   'BLOCKED',
    policy_sub_tier:  null,
    policy_rationale: f.rationale,
    hitl_status:      'PENDING',
    obligations:      [],
    status:           'FAILURE',
    error_details:    f.error_details
  });
}

function build_writer_event(c, facts) {
  return {
    correlation_id:      c.correlation_id,
    event_type:          'ASSET_RECONCILED',
    execution_id:        c.execution_id,
    agent_id:            c.agent_id,
    risk_tier:           c.risk_tier,
    inputs: {
      event_type:    'ASSET_RECONCILED',
      asset:         facts.asset,
      wallet:        facts.wallet,
      ledger:        facts.ledger,
      ratio:         facts.ratio,
      discrepancy:   facts.discrepancy,
      band_status:   facts.band_status,
      threshold:     facts.threshold,
      input_problem: facts.input_problem
    },
    ai_prompt:           null,
    ai_output:           null,
    ai_confidence:       null,
    fractional_cost_usd: null,
    policy_outcome:      facts.policy_outcome,
    policy_sub_tier:     facts.policy_sub_tier,
    policy_rationale:    facts.policy_rationale,
    obligations:         facts.obligations || [],
    hitl_status:         facts.hitl_status,
    status:              facts.status,
    error_details:       facts.error_details
  };
}

// ============================================================================
// FAO Reserve Recon - Check Writer Count
// ----------------------------------------------------------------------------
// FAO-GOV-001 / FAO-REC-001: every asset decision must be stored. The Writer
// returns one item {count, inserted[]}; the run fails here unless count
// equals the number of items Per-Asset Reconcile produced. The database also
// refuses an incomplete chain at finalize (COMMIT_BLOCKED); this check makes
// a short write fail loudly at the point it happens.
// ============================================================================

const expected = $('Per-Asset Reconcile').all().length;
const first = $input.first();
const count = first && first.json ? first.json.count : undefined;

if (count !== expected) {
  throw new Error(`FAO-GOV-001 recon: writer stored ${count} of ${expected} asset events`);
}

return [{ json: { count, expected } }];

// ============================================================================
// FAO Reserve Recon - Notify Input
// ----------------------------------------------------------------------------
// FAO-GOV-004 / FAO-GOV-007: fao_run_finalize has already created the request
// and written HITL_REQUESTED in the same transaction as the move to
// AWAITING_HITL. The notifier only notifies, and reads exactly
// {hitl_id, kind, level}; everything it posts comes from the database.
// ============================================================================

const r = (($input.first() || {}).json || {}).r || {};
const hitl_id = r.hitl_id;

if (!Number.isSafeInteger(hitl_id) || hitl_id < 1) {
  throw new Error('FAO-GOV-007 recon: finalize result has no valid hitl_id');
}

return [{ json: { hitl_id, kind: 'REQUESTED', level: 0 } }];
